 const value=$('#rwZoomValue');if(value)value.textContent=Math.round(randomZoom*100)+'%';
 const tree=$('#randomTree');if(tree){const tile=Math.max(12,Math.min(120,30*randomZoom));tree.style.setProperty('--rw-grid-tile',tile+'px');tree.style.setProperty('--rw-grid-pan-x',(randomPan.x-tile/2)+'px');tree.style.setProperty('--rw-grid-pan-y',(randomPan.y-tile/2)+'px');}
