 const snapRestingNodes=()=>{for(const item of from){const el=world.querySelector(`.rw-node[data-uid="${item.node.uid}"]`);if(!el)continue;el.style.left=item.node.dx+'px';el.style.top=item.node.dy+'px';el.style.transform='none';}};
 const drawFrame=t=>{const eased=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;for(const item of from){const fromX=Number.isFinite(item.x)?item.x:0,fromY=Number.isFinite(item.y)?item.y:0,targetX=Number.isFinite(item.node.x)?item.node.x:fromX,targetY=Number.isFinite(item.node.y)?item.node.y:fromY;item.node.dx=Math.round(fromX+(targetX-fromX)*eased);item.node.dy=Math.round(fromY+(targetY-fromY)*eased);const el=world.querySelector(`.rw-node[data-uid="${item.node.uid}"]`);if(el)el.style.transform=`translate(${item.node.dx}px,${item.node.dy}px)`;}randomPan={x:fromPan.x+(targetPan.x-fromPan.x)*eased,y:fromPan.y+(targetPan.y-fromPan.y)*eased};applyRandomTransform();redrawRandomLines();};
