  function renderAiFragments(filter=aiFragmentFilter){aiFragmentFilter=filter;const fragments=aiFragmentsOf(readAiMemory()),labels={preference:'偏好',fact:'事实',event:'事件'},counts={preference:0,fact:0,event:0};fragments.forEach(item=>counts[item.kind]++);$('#aiFragmentTotal').textContent=String(fragments.length);for(const [kind,count]of Object.entries(counts))$(`.ai-fragment-kinds [data-kind="${kind}"] b`).textContent=String(count);const categories=[...new Set(fragments.flatMap(item=>item.categories))];const filters=$('#aiFragmentFilters');filters.replaceChildren();for(const [key,label]of [['all','全部'],...categories.map(category=>[category,category])]){const button=document.createElement('button');button.type='button';button.dataset.aiFragmentFilter=key;button.setAttribute('aria-pressed',String(filter===key));button.textContent=label+(key==='all'?` ${fragments.length}`:'');filters.append(button);}const list=$('#aiFragmentList');list.replaceChildren();const visible=fragments.filter(item=>filter==='all'||item.categories.includes(filter));for(const item of visible){const card=document.createElement('article');card.className='ai-fragment-card';const text=document.createElement('p');text.textContent=item.text;const meta=document.createElement('div');meta.className='ai-fragment-meta';meta.textContent=[labels[item.kind],...item.categories,...(item.noteIds.length?[`相关笔记 ${item.noteIds.length}`]:[])].join(' · ');card.append(text,meta);if(item.noteIds[0]){card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','打开相关笔记');card.onclick=()=>window.MemoInteractions?.openDetail(item.noteIds[0]);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();window.MemoInteractions?.openDetail(item.noteIds[0]);}};}list.append(card);}$('#aiFragmentEmpty').hidden=!!visible.length;}
