    const memoryContext=`用户画像：\n${value.user||''}\n\nAI 记忆档案：\n${value.memory||''}`,button=$('#aiRunCompare');button.disabled=true;$('#aiCompareWithMemory').textContent='生成中…';$('#aiCompareWithoutMemory').textContent='生成中…';$('#aiCompareStatus').textContent='正在从记忆中生成问题…';
    let question=$('#aiCompareQuestion').textContent.trim()||'请用三句话概括你对我的了解，以及你建议我最近优先关注什么。';
