      const generated=await desktop.aiComplete({temperature:0.45,maxTokens:100,messages:[{role:'system',content:'你是 Fomo 的 Agent。请只根据下面的用户画像和记忆档案，提出一个具体、克制、开放的问题，帮助用户看见自己最近的矛盾、选择或取舍。只输出一句问题，不要解释，不要替用户下结论，不要编造记忆里没有的经历。'}, {role:'user',content:memoryContext}]});
