 const heading=[...$('#settingsStorage').querySelectorAll('h3')].find(h=>h.textContent==='备份与恢复');if(heading)heading.before(panel);else $('#settingsStorage').append(panel);
 const button=panel.querySelector('button'),apply=panel.querySelector('#applyObsidian'),reviewPreview=panel.querySelector('#previewObsidianReview'),reviewApply=panel.querySelector('#applyObsidianReview'),status=panel.querySelector('[role=status]'),details=panel.querySelector('.obsidian-conflicts');
 let previewActions=[];const connect=panel.querySelector('#connectObsidian'),pairCode=panel.querySelector('#obsidianPairCode');
 connect.onclick=async()=>{connect.disabled=true;apply.hidden=true;reviewApply.hidden=true;details.replaceChildren();try{await desktop.connectObsidian(pairCode.value);pairCode.value='';status.textContent='配对码已接收；选择同一 Fomo 文件夹后验证连接。';}catch(error){status.textContent='配对失败：'+error.message;}finally{connect.disabled=false;}};
