 if(activeTag===oldTag||activeTag.startsWith(oldTag+'/')){view='all';activeTag='';}
 renamingTag='';[...collapsedTags].filter(t=>t===oldTag||t.startsWith(oldTag+'/')).forEach(t=>collapsedTags.delete(t));rememberTagFolds();const after=MemoCore.clone(state);render();$('#dialog').close();toast('已移除标签，笔记保留',()=>undoChange(before,after));
