async function undoChange(before,after,message='标签已恢复'){if(busy)return false;busy=true;try{state=await MemoStore.save(after,before);base=MemoCore.clone(state);channel?.postMessage('saved');render();toast(message);return true;}catch(error){toast('无法撤销：'+error.message,null,{error:true});return false;}finally{busy=false;}}
function replaceRichTag(html,oldTag,newTag){
 if(!html)return '';const t=document.createElement('template');t.innerHTML=cleanHTML(html);
 const nodes=[];let text='';const walk=parent=>{for(const n of parent.childNodes){if(n.nodeType===Node.TEXT_NODE){nodes.push({node:n,start:text.length,end:text.length+n.textContent.length});text+=n.textContent;}else if(n.nodeType===Node.ELEMENT_NODE){const block=/^(P|DIV|LI|BR|H[1-6]|PRE|BLOCKQUOTE)$/.test(n.tagName);if(block)text+='\n';walk(n);if(block)text+='\n';}}};walk(t.content);
 for(const token of MemoCore.tokens(text).reverse()){const replacement=MemoCore.replaceTag(token[0],oldTag,newTag);if(replacement===token[0])continue;const start=token.index,end=start+token[0].length;const touched=nodes.filter(n=>n.start<end&&n.end>start);for(let i=touched.length-1;i>=0;i--){const {node,start:offset}=touched[i],a=Math.max(0,start-offset),b=Math.min(node.textContent.length,end-offset);node.textContent=node.textContent.slice(0,a)+(i===0?replacement:'')+node.textContent.slice(b);}}
 return t.innerHTML;
}
function reviewSettingsMarkup(){
 const r=state.review,condition=r.noTags?'noTags':r.include&&r.exclude?'custom':r.include?'include':r.exclude?'exclude':'all';
 return `<h3>每日回顾</h3><div class="settings-group review-settings-intro"><strong>每日回顾</strong><p>让过去的记录，重新带来启发。</p></div><p class="settings-caption">回顾范围</p><div class="settings-group"><div class="settings-row"><label for="reviewCondition">回顾条件</label><select id="reviewCondition">${[['all','全部内容'],['include','包含指定标签'],['exclude','排除指定标签'],['noTags','无标签'],...(condition==='custom'?[['custom','自定义组合（旧版设置）']]:[])].map(([v,t])=>`<option value="${v}" ${v===condition?'selected':''}>${t}</option>`).join('')}</select></div><div class="settings-row" id="reviewIncludeRow"><label for="reviewInclude">包含标签</label><input id="reviewInclude" value="${escape(r.include)}" placeholder="标签/子标签"></div><div class="settings-row" id="reviewExcludeRow"><label for="reviewExclude">排除标签</label><input id="reviewExclude" value="${escape(r.exclude)}" placeholder="标签/子标签"></div><div class="settings-row"><label for="reviewPeriod">时间范围</label><select id="reviewPeriod">${[['all','全部时间'],['12','1年内'],['6','6个月内'],['3','3个月内'],['1','1个月内']].map(([v,t])=>`<option value="${v}" ${v===r.period?'selected':''}>${t}</option>`).join('')}</select></div><div class="settings-row"><label for="reviewCount">回顾条数</label><select id="reviewCount">${[4,8,12,16,20,24].map(n=>`<option value="${n}" ${n===r.count?'selected':''}>${n} 条/天</option>`).join('')}</select></div></div><p class="settings-caption">每日更新</p><div class="settings-group"><div class="settings-row"><div><label for="reviewAt">系统提醒</label><small class="settings-row-note">使用本机通知提醒每日回顾</small></div><select id="reviewAt" data-previous-time="${escape(r.at||'20:00')}">${[...new Set([...Array.from({length:48},(_,i)=>String(Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00')),r.at||'20:00'])].sort().map(t=>`<option value="${escape(t)}" ${r.notify&&r.at===t?'selected':''}>${escape(t)}</option>`).join('')}<option value="off" ${!r.notify?'selected':''}>不提醒</option></select></div></div><p class="dialog-hint">保存后生效。仅回顾今天以前的记录；提醒使用本地系统通知。</p><div class="dialog-actions"><button id="cancelReview">取消</button><button id="saveReview" class="primary-button">保存回顾设置</button></div>`;
}
