async function addImages(files){
 if(busy||uploads){toast('附件正在读取，请稍候');return;}
 if(files.reduce((total,file)=>total+file.size,0)>32*1024*1024){toast('单次图片总大小请不超过 32 MB，已有草稿保留');return;}
 const revision=attachmentRevision;let failed=0,added=0;uploads++;composer.setAttribute('aria-busy','true');
 try{for(const [index,file]of files.entries()){
  if(revision!==attachmentRevision)break;
  imageReadProgress='图片 '+(index+1)+'/'+files.length;updateEditor();
  if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){failed++;continue;}
  if(file.size>8*1024*1024){failed++;continue;}
  try{const data=await readImageData(file,percent=>{if(revision!==attachmentRevision)return;imageReadProgress='图片 '+(index+1)+'/'+files.length+' · '+percent+'%';$('#charCount').textContent=imageReadProgress;});if(revision!==attachmentRevision)break;draftImages.push(data);added++;renderAttachments();}catch{failed++;}
 }}finally{uploads--;imageReadProgress='';composer.setAttribute('aria-busy','false');renderAttachments();}
 if(revision!==attachmentRevision)toast('已停止向原草稿添加图片');else if(failed)toast('已添加 '+added+' 张，'+failed+' 张未添加；仅支持 PNG、JPEG、WebP、GIF，单张不超过 8 MB。已有草稿保留');
}
$('#addAudio').onclick=audioDialog;$('#addImage').onclick=()=>$('#imageInput').click();$('#imageInput').onchange=async e=>{await addImages([...e.target.files]);e.target.value='';};
