function parseBackupDate(value){const text=String(value||'').trim().replace(/[年]/g,'-').replace(/[月]/g,'-').replace(/日/g,'').replace(/\//g,'-');const time=Date.parse(text);return Number.isFinite(time)?new Date(time).toISOString():new Date().toISOString();}
function backupAsset(assets,src){const raw=String(src||'').trim();if(!raw||/^https?:/i.test(raw)||raw.startsWith('blob:'))return '';if(raw.startsWith('data:image/'))return /^data:image\/(?:jpeg|png|webp|gif);base64,[a-zA-Z0-9+/=]+$/.test(raw)?raw:'';const key=raw.replace(/^\.\//,'').replace(/\\/g,'/');const asset=assets?.[key]||assets?.[key.split('/').pop()]||'';return /^data:image\/(?:jpeg|png|webp|gif);base64,[a-zA-Z0-9+/=]+$/.test(asset)?asset:'';}
function backupVideo(assets,src){const raw=String(src||'').trim();if(!raw||/^https?:/i.test(raw)||raw.startsWith('blob:'))return '';if(raw.startsWith('data:video/'))return /^data:video\/(?:mp4|webm|quicktime);base64,[a-zA-Z0-9+/=]+$/.test(raw)?raw:'';const key=raw.replace(/^\.\//,'').replace(/\\/g,'/');const asset=assets?.[key]||assets?.[key.split('/').pop()]||'';return /^data:video\/(?:mp4|webm|quicktime);base64,[a-zA-Z0-9+/=]+$/.test(asset)?asset:'';}
function backupAudio(assets,src){const raw=String(src||'').trim();if(!raw||/^https?:/i.test(raw)||raw.startsWith('blob:'))return '';if(raw.startsWith('data:audio/'))return /^data:audio\/(?:webm|ogg|mp4|mpeg|wav);base64,[a-zA-Z0-9+/=]+$/.test(raw)?raw:'';const key=raw.replace(/^\.\//,'').replace(/\\/g,'/');const asset=assets?.[key]||assets?.[key.split('/').pop()]||'';return /^data:audio\/(?:webm|ogg|mp4|mpeg|wav);base64,[a-zA-Z0-9+/=]+$/.test(asset)?asset:'';}
function backupText(element){if(!element)return '';const clone=element.cloneNode(true);clone.querySelectorAll('br').forEach(node=>node.replaceWith('\n'));clone.querySelectorAll('p,div,li,blockquote').forEach(node=>node.append('\n'));return clone.textContent.replace(/\n{3,}/g,'\n\n').trim();}
function backupImportSlug(value){const text=String(value||'').trim();return /^[a-zA-Z0-9_-]{1,100}$/.test(text)?text:'';}
